 T.innerHTML=`<div class="refdash rf-estate"><nav class="rf-estate-tabs" aria-label="Portfolio views">${[['portfolio','Portfolio'],['assets','Assets'],['growth','Growth'],['income','Income'],['history','History']].map(([key,label])=>`<button data-estate-tab="${key}" class="${RP.tab===key?'active':''}">${svgI(key==='portfolio'?'collection':key==='assets'?'city':key==='growth'?'resume':'progress',20)}${label}</button>`).join('')}</nav>${stats}<div class="rf-estate-context">${e.empty?'Your estate begins with your first property purchase.':esc(e.cityName)+' · '+(e.over?'Latest completed game':'Saved/current game')+' · Round '+e.round} · Rarity is your persistent collection; property ownership resets with each game.</div>${body}</div>`;
