 T.querySelectorAll('[data-property-filter]').forEach(b=>b.onclick=()=>{RP.filter=b.dataset.propertyFilter;panePortfolio(T)});
 T.querySelectorAll('[data-property-step]').forEach(b=>b.onclick=()=>{RP.square=rows[(rows.indexOf(selected)+Number(b.dataset.propertyStep)+rows.length)%rows.length].i;panePortfolio(T)});
 const fav=T.querySelector('[data-favourite]');if(fav)fav.onclick=()=>{PREF.estateFavourites=PREF.estateFavourites||{};const list=PREF.estateFavourites[e.city]||[];PREF.estateFavourites[e.city]=favourite?list.filter(v=>v!==i):[...list,i];savePref();panePortfolio(T)};
